    "Mycofall:story.title": "Geschichte",
    "Mycofall:Story_01.desc": "Vor langer Zeit,\nals der Wald noch gesund und voller Leben war, lebten die Mykari in Harmonie mit ihm. Sie waren ein kleines Volk, das aus dem Waldboden wuchs und durch die Kraft der Synergie eng mit dem Wald verbunden war.",
    "Mycofall:Story_02.desc": "Doch mit den Jahren wurden die Insekten immer zahlreicher und bedrohten die Wurzeln des Waldes. Als der Wald schwächer wurde und auch die Mykari unter der Plage litten, erwachte die Synergie zu neuer Stärke. Sie schenkte den Mykari die Gabe, mächtiges Myzel zu formen und daraus einen schimmernden Schutzfilm über die tiefen Wurzeln des Waldes zu legen.",
    "Mycofall:Story_03.desc": "Insekten, die dieses Myzel fraßen, wurden vergiftet und starben, und für lange Zeit blieben die tiefen Wurzeln des Waldes geschützt…",
    "Mycofall:Story_04.desc": "Doch die Insekten lernten...\nSie fraßen nicht gierig, nicht auf einmal. Tag für Tag nahmen sie nur Spuren des Films auf. Es schwächte sie, verzerrte ihr Inneres – doch es tötete sie nicht. Über viele Zyklen hinweg überlebten nur jene, die die Veränderung ertrugen.",
    "Mycofall:Story_05.desc": "Generation um Generation wurde widerstandsfähiger. Die Anführer jener Kolonien begannen zu wählen. Sie ließen nur jene Nachkommen leben, deren Körper den Schutzfilm nicht mehr ablehnten, sondern aufnahmen. Aus dem Schild wurde Nahrung. Aus der Veränderung wurde Macht. So entstanden die Pestisekts. Wo sie den Wald berühren, beginnt er zu verrotten.",
    "Mycofall:Story_06.desc": "Der Wald drohte erneut zu sterben, und die Mykari, einst friedlich, mussten sich verändern – so wie ihre Feinde. Das Myzel, das einst ihr Schutzfilm war, wurde nun zum Töten verwendet. Sie wurden zu Kriegern, auch jene, die es nie wollten. Denn wenn das Volk der Mykari stirbt, fällt der Wald mit ihm, und die Synergie erlischt...",
    "Mycofall:general.title": "Allgemein",
    "Mycofall:general.desc": "Mycofall ist ein Bullet-Heaven-ähnlicher Auto-Shooter im Survivors-Stil. Besiege Horden infizierter Insekten, um mächtige Fähigkeiten und Waffen zu entwickeln und zu verändern. Sammle Myzel, werde stärker, schalte permanente Upgrades frei und verteidige den Wald allein oder zusammen im Online-Koop.",
