    "UI:new": "Neu",
    "UI:newsText.title": "Deine Reise beginnt",
    "UI:newsText.desc": "<b>Hallo Shroomer,</b>\n\ndanke, dass du die Mycofall-Demo gespielt hast. Dies ist nur eine Vitrine, um die Kernmechaniken des Spiels zu präsentieren, aber es gibt noch mehr zu entdecken! Mehr Fähigkeiten, Charaktere und Karten. Inhalte und Balance sind noch in Arbeit und können sich jederzeit ändern.\n\nAls unabhängige Entwickler verlassen wir uns stark auf Playtests und Feedback, um das Spiel so gut wie möglich auszubalancieren und seine Mechaniken auf die nächste Stufe zu bringen. Daher benötigen wir Ideen, Feedback, Eindrücke und Beteiligung. Du bist herzlich eingeladen, unserem Discord beizutreten.\n\nViel Spaß mit dem Spiel.\nBleib mystisch!\n\nPS: 'Dieses Spiel ist voller Bugs.'",
    "UI:howToPlay": "Wie man spielt",
    "UI:demoEnd.title": "ENDE DER DEMO",
    "UI:demoEnd.desc": "Hallo Shroomer,\n\nDanke, dass du die Mycofall-Demo gespielt hast.\nEs gibt noch mehr zu entdecken! Mehr Fähigkeiten, Charaktere und Karten. Also klick auf den Wishlist-Button!\n\nVergiss nicht, dem Discord-Server beizutreten und Feedback zu hinterlassen, wenn du etwas teilen möchtest.",
    "UI:bonus": "Bonus",
    "UI:artifactSelection": "Artefakt Belohnung",
    "UI:newsTextAlpha.title": "Willkommen im Early Access!",
    "UI:newsTextAlpha.desc": "Hallo Shroomer,\n\nschön, dass du hier bist. Du gehörst zu den Ersten, die exklusiven Einblick in unseren Spielentwicklungsprozess bekommen. Inhalte und Balance befinden sich noch in der Entwicklung und können sich jederzeit ändern. Wir sind gerade erst am Anfang unserer Reise, also wenn du möchtest, kannst du Teil davon sein.\n\nAls unabhängige Entwickler verlassen wir uns stark auf Playtests und Feedback, um das Spiel so gut wie möglich auszubalancieren und seine Mechaniken auf die nächste Stufe zu bringen. Daher benötigen wir Ideen, Feedback, Eindrücke und Beteiligung. Du bist herzlich eingeladen, unserem Discord beizutreten.\n\nAber jetzt möchten wir dich nicht länger aufhalten — viel Spaß mit dem Spiel.\n\nBleib mystisch!\n\nPS: 'Dieses Spiel ist voller Bugs.'",
    "UI:selectedEvolutionIndicator": "STANDARD BEHALTEN",
    "UI:waitingForHost": "Warte auf Host",
    "UI:winDifficulty.title": "Glückwunsch",
    "UI:winDifficulty.desc": "Du hast eine neue Difficulty freigeschaltet.",
    "UI:tutorial": "Tutorial",
    "UI:requiredLevel": "Stufe {0} benötigt",
    "UI:default": "AUSGEWÄHLT",
    "UI:maxSkillsReached": "Maximale Skills erreicht",
    "UI:credits": "Credits",
    "UI:unseen": "Nie gesehen",
    "UI:reward": "Belohnung",
    "UI:gameOver.title": "Game Over",
    "UI:victory.title": "Sieg",
    "UI:victory.desc": "Du hast Miss Mantis besiegt.\nDoch während du deinen kleinen Sieg feierst, schlüpfen bereits mehr Insekten aus.\n\nLauf nach Hause — oder bleib hier für totale Eskalation?",
    "UI:endless": "Endlose Eskalation",
    "UI:privacyPolicy": "Datenschutzerklärung",
    "UI:firstTimePlayer.title": "Willkommen, Pilzfreund!",
    "UI:firstTimePlayer.desc": "Bevor du startest, empfehlen wir dir, das kurze Tutorial in deiner ersten Runde zu absolvieren. Es führt dich durch alle wichtigen Mechaniken, damit du wie ein Profi spielen kannst!",
    "UI:quitConfirmation.title": "Auf Wiedersehen",
