    "Mycofall:story.title": "Histoire",
    "Mycofall:Story_01.desc": "Il y a longtemps,\nquand la forêt était encore saine et pleine de vie, les Mykari vivaient en harmonie avec elle. C'était un petit peuple qui poussait du sol forestier et qui, par la puissance de la synergie, était profondément lié à la forêt.",
    "Mycofall:Story_02.desc": "Mais au fil des années, les insectes deviennent de plus en plus nombreux et menacent les racines de la forêt. Alors que la forêt s'affaiblissait et que les Mykari souffraient aussi du fléau, la synergie s'éveilla à une nouvelle force. Elle donna aux Mykari le don de façonner un puissant mycélium et de l'utiliser pour créer un film protecteur chatoyant sur les racines profondes de la forêt.",
    "Mycofall:Story_03.desc": "Les insectes qui mangeaient ce mycélium étaient empoisonnés et mouraient, et pendant longtemps les racines profondes de la forêt restaient protégées…",
    "Mycofall:Story_04.desc": "Mais les insectes ont appris…\nIls ne mangeaient pas avidement, pas tout d'un coup. Jour après jour, ils ne prenaient que des traces du film. Cela les affaiblissait, déformait leur intérieur – mais ne les tuait pas. Au cours de nombreux cycles, seuls ceux qui supportaient le changement survivaient.",
    "Mycofall:Story_05.desc": "Génération après génération devint plus résistant. Les leaders de ces colonies ont commencé à choisir. Ils laissaient vivre seulement les descendants dont les corps ne rejetaient pas le film protecteur, mais l'absorbaient. Du bouclier venait la nourriture. Du changement venait le pouvoir. Ainsi naquirent les Pestinsectes. Partout où ils touchent la forêt, elle commence à pourrir.",
    "Mycofall:Story_06.desc": "La forêt était en danger de mourir à nouveau, et les Mykari, autrefois pacifiques, ont dû changer – tout comme leurs ennemis. Le mycélium qui était autrefois leur bouclier était maintenant utilisé pour tuer. Ils sont devenus des guerriers, même ceux qui ne voulaient jamais l'être. Car si le peuple des Mykari meurt, la forêt tombe avec lui, et la synergie s'efface…",
    "Mycofall:general.title": "Général",
    "Mycofall:general.desc": "Mycofall est un jeu de tir automatique de type bullet-heaven survivors. Vainquez des hordes d'insectes infectés pour évoluer et transformer vos capacités et armes puissantes. Collectez du mycélium, devenez plus fort, débloquez des améliorations permanentes et défendez la forêt en solo ou en coopération en ligne.",
