    "UI:statistics": "Statistiques",
    "UI:new": "Nouveau",
    "UI:newsText.title": "Ton voyage commence",
    "UI:newsText.desc": "<b>Salut Shroomer,</b>\n\nmerci d'avoir joué à la démo de Mycofall. Ce n'est qu'une vitrine pour présenter les mécaniques principales du jeu, mais il y a bien plus à découvrir ! Plus de compétences, de personnages et de cartes. Le contenu et l'équilibrage sont encore en cours de développement et peuvent changer à tout moment.\n\nEn tant que développeurs indépendants, nous nous appuyons fortement sur les tests de jeu et les retours pour équilibrer le jeu au mieux et pousser ses mécaniques au niveau suivant. C'est pourquoi nous avons besoin d'idées, de retours, d'impressions et de participation. Tu es chaleureusement invité à rejoindre notre Discord.\n\nAmuse-toi bien avec le jeu.\nReste mystérieux !\n\nPS : 'Ce jeu est plein de bugs.'",
    "UI:howToPlay": "Comment jouer",
    "UI:demoEnd.title": "FIN DE LA DÉMO",
    "UI:demoEnd.desc": "Salut Shroomer,\n\nMerci d'avoir joué à la démo de Mycofall.\nIl y a encore plus à découvrir ! Plus de compétences, de personnages et de cartes. Alors clique sur le bouton liste de souhaits !\n\nN'oublie pas de rejoindre le serveur Discord et de laisser des commentaires si tu veux partager quelque chose.",
    "UI:bonus": "Bonus",
    "UI:artifactSelection": "Récompense d'artefact",
    "UI:newsTextAlpha.title": "Bienvenue dans l'Accès Anticipé !",
    "UI:newsTextAlpha.desc": "Salut Shroomer,\n\nravi de t'avoir ici. Tu fais partie des premiers à découvrir notre processus de développement de jeu en exclusivité. Le contenu et l'équilibrage sont encore en cours de développement et peuvent changer à tout moment. Nous ne sommes qu'au début de notre voyage, donc si tu le souhaites, tu peux en faire partie.\n\nEn tant que développeurs indépendants, nous nous appuyons fortement sur les tests de jeu et les retours pour équilibrer le jeu au mieux et pousser ses mécaniques au niveau suivant. C'est pourquoi nous avons besoin d'idées, de retours, d'impressions et de participation. Tu es chaleureusement invité à rejoindre notre Discord.\n\nMais maintenant, nous ne voulons pas te retenir plus longtemps — amuse-toi bien avec le jeu.\n\nReste mystérieux !\n\nPS : 'Ce jeu est plein de bugs.'",
    "UI:selectedEvolutionIndicator": "GARDER PAR DÉFAUT",
    "UI:waitingForHost": "En attente de l'hôte",
    "UI:winDifficulty.title": "Félicitations",
    "UI:winDifficulty.desc": "Tu as débloqué une nouvelle difficulté.",
    "UI:tutorial": "Tutoriel",
