    "UI:credits": "Crédits",
    "UI:unseen": "Jamais vu",
    "UI:reward": "Récompense",
    "UI:gameOver.title": "Game Over",
    "UI:victory.title": "Victoire",
    "UI:victory.desc": "Tu as vaincu Miss Mantis.\nMais pendant que tu célèbres ta petite victoire, encore plus d'insectes sont déjà en train d'éclore.\n\nCours à la maison — ou reste pour une escalade totale ?",
    "UI:endless": "Escalade infinie",
    "UI:privacyPolicy": "Politique de confidentialité",
    "UI:firstTimePlayer.title": "Bienvenue, amateur de champignons !",
    "UI:firstTimePlayer.desc": "Avant de commencer, nous vous suggérons de terminer le court tutoriel dans votre première partie. Il vous guidera à travers toutes les mécaniques essentielles pour que vous soyez prêt à jouer comme un pro !",
    "UI:quitConfirmation.title": "Au revoir",
