    "Mycofall:story.title": "Historia",
    "Mycofall:Story_01.desc": "Hace mucho tiempo,\ncuando el bosque aún estaba sano y lleno de vida, los Mykari vivían en armonía con él. Eran un pequeño pueblo que crecía del suelo del bosque y estaban profundamente conectados con el bosque a través del poder de la sinergia.",
    "Mycofall:Story_02.desc": "Pero con el paso de los años, los insectos se volvieron cada vez más numerosos y amenazaron las raíces del bosque. Mientras el bosque se debilitaba y los Mykari también sufrían la plaga, la sinergia se despertó a una nueva fuerza. Ella dio a los Mykari el don de moldear un poderoso micelio y usarlo para crear una película protectora reluciente sobre las raíces profundas del bosque.",
    "Mycofall:Story_03.desc": "Los insectos que comían este micelio fueron envenenados y murieron, y durante mucho tiempo las raíces profundas del bosque permanecieron protegidas…",
    "Mycofall:Story_04.desc": "Pero los insectos aprendieron…\nNo comían con avidez, no todo de una vez. Día tras día, solo tomaban trazas de la película. Los debilitaba, distorsionaba su interior – pero no los mataba. Durante muchos ciclos, solo aquellos que soportaban el cambio sobrevivían.",
    "Mycofall:Story_05.desc": "Generación tras generación se volvieron más resistentes. Los líderes de estas colonias comenzaron a elegir. Dejaban vivir solo a la descendencia cuyos cuerpos no rechazaban la película protectora, sino que la absorbían. Del escudo vino la comida. Del cambio vino el poder. Así nacieron los Insectos Plaga. Donde quiera que toquen el bosque, comienza a pudrirse.",
    "Mycofall:Story_06.desc": "El bosque estaba en peligro de morir nuevamente, y los Mykari, una vez pacíficos, tuvieron que cambiar – como sus enemigos. El micelio que una vez fue su escudo ahora se usaba para matar. Se convirtieron en guerreros, incluso aquellos que nunca quisieron serlo. Porque si el pueblo de los Mykari muere, el bosque cae con él, y la sinergia se desvanece…",
    "Mycofall:general.title": "General",
    "Mycofall:general.desc": "Mycofall — это автоматический шутер в стиле bullet-heaven survivors. Победи орды инфицированных насекомых, чтобы развиваться и трансформировать мощные способности и оружие. Собирай мицелий, становись сильнее, разблокируй постоянные улучшения и защищай лес в одиночку или вместе в онлайн кооперативе.",
