    "UI:new": "Nuevo",
    "UI:newsText.title": "Tu viaje comienza",
    "UI:newsText.desc": "<b>Hola Shroomer,</b>\n\ngracias por jugar la demo de Mycofall. ¡Esto es solo una muestra para presentar la mecánica central del juego, pero hay mucho más por descubrir! Más habilidades, personajes y mapas. El contenido y el balance aún están en progreso y pueden cambiar en cualquier momento.\n\nComo desarrolladores independientes, confiamos mucho en las pruebas de juego y los comentarios para equilibrar el juego lo mejor posible e impulsar sus mecánicas al siguiente nivel. Por eso necesitamos ideas, comentarios, impresiones e involucración. ¡Eres cordialmente invitado a unirte a nuestro Discord!\n\nDiviértete con el juego.\n¡Mantente misterioso!\n\nPS: 'Este juego está lleno de bugs.'",
    "UI:howToPlay": "Cómo jugar",
    "UI:demoEnd.title": "FIN DE LA DEMO",
    "UI:demoEnd.desc": "Hola Shroomer,\n\nGracias por jugar la demo de Mycofall.\n¡Hay más por descubrir! Más habilidades, personajes y mapas. ¡Así que presiona el botón de lista de deseados!\n\nNo olvides unirte al servidor de Discord y dejar comentarios si quieres compartir algo.",
    "UI:bonus": "Bonus",
    "UI:artifactSelection": "Recompensa de artefacto",
    "UI:newsTextAlpha.title": "¡Bienvenido al Acceso Anticipado!",
    "UI:newsTextAlpha.desc": "Hola Shroomer,\n\nme alegra tenerte aquí. Eres uno de los primeros en obtener acceso exclusivo a nuestro proceso de desarrollo de juegos. El contenido y el balance aún están en desarrollo y pueden cambiar en cualquier momento. Estamos en el inicio de nuestro viaje, así que si lo deseas, puedes ser parte de él.\n\nComo desarrolladores independientes, confiamos mucho en las pruebas de juego y los comentarios para equilibrar el juego lo mejor posible e impulsar sus mecánicas al siguiente nivel. Por eso necesitamos ideas, comentarios, impresiones e involucración. ¡Eres cordialmente invitado a unirte a nuestro Discord!\n\nPero ahora no queremos detenerte más — diviértete con el juego.\n\n¡Mantente misterioso!\n\nPS: 'Este juego está lleno de bugs.'",
