    "UI:victory.desc": "Has derrotado a Miss Mantis.\nPero mientras celebras tu pequeña victoria, más insectos ya están eclosionando.\n\n¿Corre a casa o quédate para una escalada total?",
    "UI:endless": "Escalada infinita",
