    "Skills:thorns.desc": "Призывает колючие наросты из земли, поражающие ближайших врагов.",
    "Skills:spores.desc": "Создаёт вокруг игрока споровую ауру, периодически наносящую урон ближайшим врагам.",
    "Skills:boomerang.desc": "Бросает из позиции игрока колючие бумеранги, поражающие всё на своём пути.",
    "Skills:pineconeRain.desc": "Призывает с неба шишечный метеорит, нацеленный на врага и наносящий урон по области при ударе.",
    "Skills:plantBombs.desc": "Создаёт растительные бомбы на большой области, которые игрок может активировать, нанося урон по области всем врагам в радиусе.",
    "Skills:slash.title": "Клинок Гнили",
    "Skills:slash.desc": "Размахивает Клинком Гнили рядом с игроком. Все враги в зоне действия получают удар.",
    "Skills:beam.title": "Гифовый мост",
    "Skills:beam.desc": "Связывается с ближайшим противником и непрерывно наносит урон",
    "Characters:wortak.desc": "Созданный выстоять, он стоит твердо там, где другие падают.",
