    "Interactables:BiomassEvent.title": "Биомасса",
    "Interactables:BiomassEvent.desc": "Создает подборки Биомассы. Количество масштабируется в зависимости от текущей волны.",
    "Interactables:BossRewardEvent.title": "Награда Босса",
    "Interactables:BossRewardEvent.desc": "Создает бонусную добычу артефактов, выдаваемую после победы над боссом.",
    "Interactables:EnemySpawnEvent.title": "Спаун врага",
    "Interactables:EnemySpawnEvent.desc": "Создает Lord Rammhorn для игроков, чтобы они могли сражаться.",
    "Interactables:HealEvent.title": "Пузырь исцеления",
    "Interactables:HealEvent.desc": "Создает пузырь исцеления, восстанавливающий здоровье.",
    "Interactables:LootMagnetEvent.title": "Магнит добычи",
    "Interactables:LootMagnetEvent.desc": "Создает подборку, которая притягивает близлежащую добычу к игроку.",
    "Interactables:SpeedBubbleEvent.title": "Пузырь скорости",
    "Interactables:SpeedBubbleEvent.desc": "Создает пузырь, который временно увеличивает скорость движения.",
    "Interactables:RammhornRewardEvent.title": "Элитная награда",
    "Interactables:RammhornRewardEvent.desc": "Создает бонусную добычу артефактов, выдаваемую после победы над Lord Rammhorn.",
    "Resources:Amber.title": "Янтарь",
    "Resources:Amber.desc": "Вторичный ресурс во время прохождения, используемый для более дорогих покупок морфов. Создаётся событием взаимодействия Янтарь и предоставляется некоторыми артефактами.",
    "Resources:Biomass.title": "Биомасса",
    "Resources:Biomass.desc": "Вторичный ресурс во время прохождения, используемый для более дорогих покупок морфов. Падает от противников и создаётся событием взаимодействия Биомасса.",
    "Resources:MetaMushroom.title": "Метамицелий",
    "Resources:MetaMushroom.desc": "Постоянная валюта, собираемая из грибных предметов во время прохождения. Сохраняется между прохождениями и тратится в Хабе для разблокировки новых навыков, карт и персонажей.",
    "Resources:Mycelium.title": "Мицелий",
    "Resources:Mycelium.desc": "Основная валюта во время прохождения, заработанная путём победы над противниками и сбора предметов. Потрачена в магазине на морфы навыков.",
