    "Mycofall:story.title": "История",
    "Mycofall:Story_01.desc": "Давно, когда-то,\nкогда лес был ещё здоров и полон жизни, Мыкари жили в гармонии с ним. Это был малый народ, выросший из лесной почвы и глубоко связанный с лесом благодаря силе синергии.",
    "Mycofall:Story_02.desc": "Но с течением времени насекомых становилось всё больше, они угрожали корням леса. Когда лес слабел и Мыкари также страдали от бедствия, синергия пробудилась к новой силе. Она дала Мыкари дар формировать мощный мицелий и использовать его, чтобы создать мерцающую защитную плёнку над глубокими корнями леса.",
    "Mycofall:Story_03.desc": "Насекомые, которые ели этот мицелий, отравлялись и умирали, и долгое время глубокие корни леса оставались защищены…",
    "Mycofall:Story_04.desc": "Но насекомые научились…\nОни ели не жадно, не сразу все. День за днём они брали только следы плёнки. Это их ослабляло, искажало их внутренности – но не убивало их. На протяжении многих циклов выживали только те, кто переносил изменения.",
    "Mycofall:Story_05.desc": "Поколение за поколением становились более устойчивыми. Лидеры этих колоний начали выбирать. Они оставляли в живых только тех потомков, чьи тела не отвергали защитную плёнку, а поглощали её. Из щита пришла еда. Из изменения пришла сила. Так родились Чумные насекомые. Везде, где они касаются леса, он начинает гнить.",
    "Mycofall:Story_06.desc": "Лес был в опасности снова умереть, и Мыкари, некогда мирные, должны были измениться – как и их враги. Мицелий, который когда-то был их щитом, теперь использовался для убийства. Они стали воинами, даже те, кто никогда этого не хотел. Ибо если народ Мыкари умрёт, лес упадёт вместе с ним, и синергия угаснет…",
    "Mycofall:general.title": "Общие",
    "Mycofall:general.desc": "Mycofall — это автоматический шутер в стиле bullet-heaven survivors. Победи орды инфицированных насекомых, чтобы развиваться и трансформировать мощные способности и оружие. Собирай мицелий, становись сильнее, разблокируй постоянные улучшения и защищай лес в одиночку или вместе в онлайн кооперативе.",
