    "UI:new": "Новая",
    "UI:newsText.title": "Твоё путешествие начинается",
    "UI:newsText.desc": "<b>Привет, Shroomer,</b>\n\nспасибо, что играли в демо-версию Mycofall. Это всего лишь витрина для демонстрации основных механик игры, но есть ещё много чего открыть! Больше навыков, персонажей и карт. Контент и баланс ещё в разработке и могут изменяться в любой момент.\n\nКак независимые разработчики, мы сильно полагаемся на тестирование игры и отзывы, чтобы как можно лучше сбалансировать игру и поднять её механики на новый уровень. Вот почему нам нужны идеи, отзывы, впечатления и участие. Мы сердечно приглашаем тебя присоединиться к нашему Discord.\n\nВеселись с игрой.\nОставайся загадочным!\n\nPS: 'Эта игра полна ошибок.'",
    "UI:howToPlay": "Как играть",
    "UI:demoEnd.title": "КОНЕЦ ДЕМО",
    "UI:demoEnd.desc": "Привет, Shroomer,\n\nСпасибо, что сыграли в демо-версию Mycofall.\nЗдесь есть ещё что открыть! Больше умений, персонажей и карт. Так что нажми на кнопку списка желаемого!\n\nНе забудь присоединиться к Discord-серверу и оставить отзыв, если хочешь чем-то поделиться.",
    "UI:bonus": "Бонус",
    "UI:artifactSelection": "Награда артефакта",
    "UI:newsTextAlpha.title": "Добро пожаловать в ранний доступ!",
    "UI:newsTextAlpha.desc": "Привет, Shroomer,\n\nрады тебя видеть. Ты один из первых, кто получает эксклюзивный доступ к нашему процессу разработки игры. Контент и баланс ещё в разработке и могут изменяться в любой момент. Мы только в начале нашего путешествия, поэтому если ты хочешь, ты можешь быть его частью.\n\nКак независимые разработчики, мы сильно полагаемся на тестирование игры и отзывы, чтобы как можно лучше сбалансировать игру и поднять её механики на новый уровень. Вот почему нам нужны идеи, отзывы, впечатления и участие. Мы сердечно приглашаем тебя присоединиться к нашему Discord.\n\nНо теперь мы не хотим больше тебя задерживать — веселись с игрой.\n\nОставайся загадочным!\n\nPS: 'Эта игра полна ошибок.'",
    "UI:selectedEvolutionIndicator": "ОСТАВИТЬ ПО УМОЛЧАНИЮ",
    "UI:waitingForHost": "Ожидание хоста",
    "UI:winDifficulty.title": "Поздравления",
    "UI:winDifficulty.desc": "Ты разблокировал новую сложность.",
    "UI:tutorial": "Обучение",
    "UI:requiredLevel": "Нужен уровень {0}",
    "UI:default": "ВЫБРАНО",
    "UI:maxSkillsReached": "Максимальное количество навыков достигнуто",
    "UI:credits": "Благодарности",
    "UI:unseen": " Не замечено",
    "UI:reward": "Награда",
    "UI:gameOver.title": "Game Over",
    "UI:victory.title": "Победа",
    "UI:victory.desc": "Ты победил Miss Mantis.\nНо пока ты празднуешь свою крошечную победу, уже вылупляются ещё больше насекомых.\n\nБеги домой — или оставайся для полной эскалации?",
    "UI:endless": "Бесконечная эскалация",
    "UI:privacyPolicy": "Политика конфиденциальности",
    "UI:firstTimePlayer.title": "Добро пожаловать, любитель грибов!",
    "UI:firstTimePlayer.desc": "Прежде чем начать, мы рекомендуем вам пройти краткое обучение в первом раунде. Оно проведет вас через все основные механики, чтобы вы были готовы играть как профессионал!",
    "UI:quitConfirmation.title": "До свидания",
    "UI:quitConfirmation.desc": "Спасибо за игру. :) Поделитесь с нами своим отзывом.",
    "UI:host": "Хост",
    "UI:join": "Присоединиться",
    "UI:yourIP": "Ваш IP",
    "UI:enterIP": "Введите IP хоста ..."
