    "Artifacts:CriticalMind.desc": "全力一击，暴击必至。",
    "Artifacts:FortuneSpore.title": "幸运孢子",
    "Artifacts:FortuneSpore.desc": "几率上升，暴击惊喜。",
    "Artifacts:Heartroot.title": "心根",
    "Artifacts:Heartroot.desc": "心灵恢复，伤口无视。",
    "Artifacts:Jumper.title": "跳跃者",
    "Artifacts:Jumper.desc": "再次冲刺，移动称王。",
    "Artifacts:RunAndGun.title": "奔跑射击",
    "Artifacts:RunAndGun.desc": "速度越快，伤害越高。",
    "Artifacts:Thornshield.title": "荆棘盾",
    "Artifacts:Thornshield.desc": "击中护盾，自食其果。",
    "Artifacts:ForestTribute.title": "森林贡品",
    "Artifacts:ForestTribute.desc": "献上祭品，礼物降临。",
    "Artifacts:LastBreathFury.title": "最后一息之怒",
    "Artifacts:LastBreathFury.desc": "生命越少，怒火越高。",
    "Artifacts:LuckyBark.title": "幸运树皮",
    "Artifacts:LuckyBark.desc": "幸运的火花，坚硬的树皮。",
    "Artifacts:SporeDash.title": "孢子冲刺",
    "Artifacts:SporeDash.desc": "冲刺过地面，孢子即发现。",
    "Artifacts:BloomOfRenewal.title": "重生之花",
    "Artifacts:BloomOfRenewal.desc": "等级提升，生命回应。",
    "Artifacts:HealingDash.title": "治疗冲刺",
    "Artifacts:HealingDash.desc": "冲刺过地面，再次得治疗。",
    "Artifacts:SlimySnail.title": "黏糊蜗牛",
    "Artifacts:SlimySnail.desc": "缓慢滑行，伤口愈合。",
    "Artifacts:OldShoes.title": "旧鞋",
    "Artifacts:OldShoes.desc": "你闻不到也看不见它们，但它们助你行走。",
    "Artifacts:MushroomBasket.title": "蘑菇篮",
    "Artifacts:MushroomBasket.desc": "有个好篮子，蘑菇立刻找。",
    "Artifacts:MeatDetector.title": "肉类探测器",
    "Artifacts:MeatDetector.desc": "探测器一用，肉类速消。",
    "Skills:fungalBlast.title": "真菌爆射",
    "Skills:thorns.title": "荆棘",
    "Skills:spores.title": "孢子",
    "Skills:boomerang.title": "回旋镖",
    "Skills:pineconeRain.title": "松果之雨",
    "Skills:plantBombs.title": "植物炸弹",
    "Skills:fungalBlast.desc": "向敌人直线发射一枚孢子弹。",
    "Skills:thorns.desc": "从地面召唤带刺的生长物，攻击附近的敌人。",
    "Skills:spores.desc": "在玩家周围释放充满孢子的光环，对附近敌人造成周期性伤害。",
    "Skills:boomerang.desc": "从玩家位置投掷带刺的回旋镖投射物，击中路径上的一切目标。",
    "Skills:pineconeRain.desc": "从空中召唤一枚锁定敌人的松果陨石，落地时造成范围伤害。",
    "Skills:plantBombs.desc": "在大范围内生成植物炸弹，玩家可引爆它们，对范围内所有敌人造成范围伤害。",
    "Skills:slash.title": "腐刃",
    "Skills:slash.desc": "在玩家附近挥动腐刃，命中作用范围内的所有敌人。",
    "Skills:beam.title": "菌丝桥",
    "Skills:beam.desc": "连接最近的敌人并持续造成伤害。",
    "Characters:wortak.desc": "为承受而生，他在他人倒下之处依然屹立不倒。",
    "Characters:ensa.desc": "她以无与伦比的优雅与速度踏入战斗。",
    "Characters:vaylen.desc": "真正的弱者，准备证明自己的价值。",
    "Characters:mo ying.desc": "迅速生长，足以在森林最黑暗的夜晚中存活。",
