    "Mycofall:story.title": "故事",
    "Mycofall:Story_01.desc": "很久以前，\n当森林仍然健康且充满生命时，Mykari与它和谐共处。 他们是一个从森林地板生长出来的小民族，通过协同力的力量 与森林紧密相连。",
    "Mycofall:Story_02.desc": "但随着岁月流逝，昆虫数量越来越多，威胁到森林的根部。 当森林变得虚弱， Mykari也遭受瘟疫之苦时， 协同力唤醒了新的力量。 她赐予Mykari 塑造强大菌丝体的天赋，并用它在 森林深处的根部上方创造 闪闪发光的保护膜。",
    "Mycofall:Story_03.desc": "吃这种菌丝体的昆虫被中毒并死亡， 森林的深根保持受保护的状态很长一段时间……",
    "Mycofall:Story_04.desc": "但昆虫学会了……\n他们没有贪心地吃，不是一次全部吃。 日复一日，他们只吸取 膜的痕迹。它削弱了他们， 扭曲了他们的内部——但没有杀死他们。 在许多周期中，只有那些 能承受变化的人活了下来。",
    "Mycofall:Story_05.desc": "代代相传变得更有抵抗力。 这些殖民地的领导者开始选择。 他们只让那些身体不排斥保护膜的后代活下来， 而是吸收它。 从盾牌来的食物。 从变化来的力量。 就这样，害虫诞生了。 无论它们触及森林的何处，森林就开始腐烂。",
    "Mycofall:Story_06.desc": "森林再次濒临死亡， 曾经和平的Mykari 不得不改变——就像他们的敌人一样。 曾经是他们盾牌的菌丝体 现在被用来杀人。 他们成为了战士， 甚至是那些从不想成为战士的人。 因为如果Mykari人民死亡， 森林就会随之倒下，协同力也会消退……",
    "Mycofall:general.title": "常规",
    "Mycofall:general.desc": "Mycofall是一款类似子弹天堂的生存者风格自动射击游戏。击败大量被感染的昆虫，进化并改变强大的能力和武器。收集菌丝体，变得更强大，解锁永久升级，并单独或在线合作防卫森林。",
