    "UI:newsText.desc": "<b>你好，Shroomer，</b>\n\n感谢你游玩Mycofall演示版。这只是一个展示游戏核心机制的橱窗，但还有更多东西等待发现！更多技能、角色和地图。内容和平衡仍在进行中，可能随时变更。\n\n作为独立开发者，我们严重依赖于游戏测试和反馈，以尽可能平衡游戏并将其机制推向下一个级别。这就是为什么我们需要想法、反馈、印象和参与。欢迎加入我们的Discord。\n\n祝你游戏愉快。\n保持神秘！\n\nPS：'这个游戏充满了bugs。'",
    "UI:howToPlay": "如何游玩",
    "UI:demoEnd.title": "演示版结束",
    "UI:demoEnd.desc": "嗨，Shroomer，\n\n感谢你游玩Mycofall演示版。\n还有更多内容等待发现！更多技能、角色和地图。所以快点击心愿单按钮吧！\n\n别忘了加入Discord服务器，如果你想分享什么，请留下反馈。",
    "UI:bonus": "奖励",
    "UI:artifactSelection": "神器奖励",
    "UI:newsTextAlpha.title": "欢迎来到抢先体验！",
    "UI:newsTextAlpha.desc": "你好，Shroomer，\n\n很高兴有你在这里。你是最早获得我们游戏开发过程独家见解的人之一。内容和平衡仍在开发中，可能随时变更。我们才刚开始这段旅程，所以如果你愿意，你可以成为其中的一部分。\n\n作为独立开发者，我们严重依赖于游戏测试和反馈，以尽可能平衡游戏并将其机制推向下一个级别。这就是为什么我们需要想法、反馈、印象和参与。欢迎加入我们的Discord。\n\n但现在我们不想再耽搁你了——祝你游戏愉快。\n\n保持神秘！\n\nPS：'这个游戏充满了bugs。'",
    "UI:selectedEvolutionIndicator": "保持默认",
    "UI:waitingForHost": "等待主机",
    "UI:winDifficulty.title": "恭喜",
    "UI:winDifficulty.desc": "你解锁了新难度。",
    "UI:tutorial": "教程",
    "UI:requiredLevel": "需要等级{0}",
    "UI:default": "已选择",
    "UI:maxSkillsReached": "达到最大技能数",
    "UI:credits": "片尾字幕",
    "UI:unseen": "未见",
    "UI:reward": "奖励",
    "UI:gameOver.title": "Game Over",
    "UI:victory.title": "胜利",
    "UI:victory.desc": "你击败了Miss Mantis。\n但当你庆祝你的微小胜利时，更多的昆虫已经孵化。\n\n跑回家——或留下来进行总体升级？",
    "UI:endless": "无尽升级",
    "UI:privacyPolicy": "隐私政策",
    "UI:firstTimePlayer.title": "欢迎，蘑菇爱好者！",
    "UI:firstTimePlayer.desc": "在你开始之前，我们建议你在第一局完成简短的教程。它会指导你了解所有核心机制，这样你就可以像专业人士一样玩了！",
    "UI:quitConfirmation.title": "再见",
    "UI:quitConfirmation.desc": "感谢你的游戏。:) 请与我们分享你的反馈。",
    "UI:host": "主机",
    "UI:join": "加入",
    "UI:yourIP": "你的IP",
    "UI:enterIP": "输入主机IP ..."
