    "Artifacts:CriticalMind.title": "クリティカルマインド",
    "Artifacts:CriticalMind.desc": "力で打て、クリティカルが勝負を決める。",
    "Artifacts:FortuneSpore.title": "幸運の胞子",
    "Artifacts:FortuneSpore.desc": "運が高まり、クリティカルが驚きをもたらす。",
    "Artifacts:Heartroot.title": "ハートルート",
    "Artifacts:Heartroot.desc": "心は癒え、傷は無視される。",
    "Artifacts:Jumper.title": "ジャンパー",
    "Artifacts:Jumper.desc": "再びダッシュ、動きが支配する。",
    "Artifacts:RunAndGun.title": "ランアンドガン",
    "Artifacts:RunAndGun.desc": "速く動くほど、ダメージが増す。",
    "Artifacts:Thornshield.title": "ソーンシールド",
    "Artifacts:Thornshield.desc": "殻を叩けば、痛みが返る。",
    "Artifacts:ForestTribute.title": "森の貢物",
    "Artifacts:ForestTribute.desc": "捧げれば、恵みが現れる。",
    "Artifacts:LastBreathFury.title": "ラストブレスフューリー",
    "Artifacts:LastBreathFury.desc": "命が尽きるほど、怒りが燃え上がる。",
    "Artifacts:LuckyBark.title": "ラッキーバーク",
    "Artifacts:LuckyBark.desc": "幸運の輝き、硬い樹皮。",
    "Artifacts:SporeDash.title": "スポアダッシュ",
    "Artifacts:SporeDash.desc": "地を駆けて、胞子が広がる。",
    "Artifacts:BloomOfRenewal.title": "再生の花",
    "Artifacts:BloomOfRenewal.desc": "レベルが上がるたび、体力が答える。",
    "Artifacts:HealingDash.title": "ヒーリングダッシュ",
    "Artifacts:HealingDash.desc": "地を駆けて、また癒される。",
    "Artifacts:SlimySnail.title": "ぬめりカタツムリ",
    "Artifacts:SlimySnail.desc": "ゆっくり滑り、傷は癒える。",
    "Artifacts:OldShoes.title": "古い靴",
    "Artifacts:OldShoes.desc": "臭くて見栄えも悪いが、逃げる助けになる。",
    "Artifacts:MushroomBasket.title": "キノコかご",
    "Artifacts:MushroomBasket.desc": "立派なかごを持って、キノコを見つける。",
    "Artifacts:MeatDetector.title": "ミートディテクター",
    "Artifacts:MeatDetector.desc": "装置を使えば、肉がすぐ見つかる。",
    "Skills:fungalBlast.title": "ファンガルブラスター",
    "Skills:thorns.title": "トゲ",
    "Skills:spores.title": "胞子",
    "Skills:boomerang.title": "ブーメラン",
    "Skills:pineconeRain.title": "松ぼっくりの雨",
    "Skills:plantBombs.title": "植物爆弾",
    "Skills:fungalBlast.desc": "敵に向かって胞子の弾を直線に発射する。",
    "Skills:thorns.desc": "地面からトゲのある芽を召喚し、近くの敵を攻撃する。",
    "Skills:spores.desc": "プレイヤーの周囲に胞子の満ちたオーラを放ち、近くの敵に定期的なダメージを与える。",
    "Skills:boomerang.desc": "プレイヤーからトゲのあるブーメランを投げ、進路上のすべてを攻撃する。",
    "Skills:pineconeRain.desc": "空から松ぼっくりの隕石を呼び寄せ、敵を狙って着弾時に範囲ダメージを与える。",
    "Skills:plantBombs.desc": "広範囲に植物爆弾を設置し、プレイヤーが起爆させることで範囲内の全敵に範囲ダメージを与える。",
    "Skills:slash.title": "腐刃",
    "Skills:slash.desc": "プレイヤーの近くで腐刃を振る。影響範囲内のすべての敵に命中する。",
    "Skills:beam.title": "菌糸の橋",
    "Skills:beam.desc": "最も近い敵に接続し、継続的にダメージを与える。",
    "Characters:wortak.desc": "耐えるために生まれ、他が倒れる場所で彼は踏み堪える。",
    "Characters:ensa.desc": "比類なき優雅さと速さで、彼女は戦場に踏み込む。",
    "Characters:vaylen.desc": "真のアンダードッグ、自分の価値を証明する準備ができている。",
    "Characters:mo ying.desc": "速く育ち、森の最も暗い夜を生き抜くために鍛えられた。",
