    "Mycofall:story.title": "ストーリー",
    "Mycofall:Story_01.desc": "昔々、\n森がまだ健康で生命に満ちていた時代、Mykariはそれと調和して生きていました。 彼らは森の床から成長した小さな民族で、 シナジーの力を通じて森と深く結びついていました。",
    "Mycofall:Story_02.desc": "しかし、年月が経つにつれて、昆虫がますます増加し、森の根を脅かすようになりました。 森が弱くなり、 Mykariも疫病に苦しむようになると、 シナジーは新しい力で目覚めました。 彼女はMykariに 強力な菌糸体を形成し、それを使用して 森の深い根の上に きらめく保護膜を作成する能力を与えました。",
    "Mycofall:Story_03.desc": "この菌糸体を食べた昆虫は毒を食らい、死にました。 そして長い間、森の深い根は保護されたままでした……",
    "Mycofall:Story_04.desc": "しかし、昆虫は学びました……\n彼らは貪欲に食べませんでした、一度にすべてを食べるのではなく。 日々、彼らは 膜のわずかな痕跡だけを取りました。それは彼らを弱めて、 内部を歪ませました──しかし彼らを殺しませんでした。 多くのサイクルにわたって、 変化に耐えた者だけが生き残りました。",
    "Mycofall:Story_05.desc": "世代ごとにより抵抗力が増しました。 これらの植民地の指導者たちは選択を始めました。 保護膜を拒否せず吸収する体を持つ子孫だけを生かしました。 盾から食べ物が来ました。 変化から力が来ました。 こうしてペストの昆虫が生まれました。 彼らが森に触れる場所はどこでも、森は腐り始めます。",
    "Mycofall:Story_06.desc": "森は再び死の危険にさらされていました。 かつて平和だったMykariは 敵と同じように変わらなければなりませんでした。 かつては盾だった菌糸体は 今は殺すために使われました。 彼らは戦士になりました。 そうなりたくなかった人たちでさえ。 Mykari の民が死ぬと、 森も一緒に倒れ、シナジーも消えます……",
    "Mycofall:general.title": "一般",
    "Mycofall:general.desc": "Mycofallはバレット・ヘブン風サバイバーズ・オートシューター。感染した昆虫の大群を倒して、強力な能力と武器を進化させ、形を変える。菌糸体を集め、より強くなり、永続的なアップグレードを解放し、森を守る。ソロまたはオンラインの協力プレイで。",
