    "Skills:fungalBlast.title": "真菌爆射",
    "Skills:thorns.title": "荊棘",
    "Skills:spores.title": "孢子",
    "Skills:boomerang.title": "回旋鏢",
    "Skills:pineconeRain.title": "松果之雨",
    "Skills:plantBombs.title": "植物炸彈",
    "Skills:fungalBlast.desc": "向敵人直線發射一枚孢子彈。",
    "Skills:thorns.desc": "從地面召喚帶刺的生長物，攻擊附近的敵人。",
    "Skills:spores.desc": "在玩家周圍釋放充滿孢子的光環，對附近敵人造成周期性傷害。",
    "Skills:boomerang.desc": "從玩家位置投擲帶刺的回旋鏢投射物，擊中路徑上的一切目標。",
    "Skills:pineconeRain.desc": "從空中召喚一枚鎖定敵人的松果隕石，落地時造成範圍傷害。",
    "Skills:plantBombs.desc": "在大範圍內生成植物炸彈，玩家可引爆它們，對範圍內所有敵人造成範圍傷害。",
    "Skills:slash.title": "腐刃",
    "Skills:slash.desc": "在玩家附近揮動腐刃，命中作用範圍內的所有敵人。",
    "Skills:beam.title": "菌絲橋",
    "Skills:beam.desc": "連接最近的敵人並持續造成傷害。",
    "Characters:wortak.desc": "為承受而生，他在他人倒下之處依然屹立不倒。",
    "Characters:ensa.desc": "她以無與倫比的優雅與速度踏入戰鬥。",
    "Characters:vaylen.desc": "真正的弱者，準備證明自己的價值。",
    "Characters:mo ying.desc": "迅速生長，足以在森林最黑暗的夜晚中存活。",
