    "Resources:MetaMushroom.desc": "一種持久的貨幣，在遊戲過程中從蘑菇拾取物中收集。在多次遊戲中保留，並在樞紐中花費以解鎖新的技能、地圖和角色。",
    "Resources:Mycelium.title": "菌絲體",
    "Resources:Mycelium.desc": "在一次遊戲過程中的主要貨幣，通過擊敗敵人和拾取物品獲得。在商店中花費以購買技能變體。",
