    "Mycofall:story.title": "故事",
    "Mycofall:Story_01.desc": "很久以前，\n當森林仍然健康且充滿生命時，Mykari與它和諧共處。他們是一個從森林地板生長出來的小民族，通過協同力的力量與森林緊密相連。",
    "Mycofall:Story_02.desc": "但隨著歲月流逝，昆蟲數量越來越多，威脅到森林的根部。當森林變得虛弱，Mykari也遭受瘟疫之苦時，協同力喚醒了新的力量。她賜予Mykari塑造強大菌絲體的天賦，並用它在森林深處的根部上方創造閃閃發光的保護膜。",
    "Mycofall:Story_03.desc": "吃這種菌絲體的昆蟲被中毒並死亡，森林的深根保持受保護的狀態很長一段時間……",
    "Mycofall:Story_04.desc": "但昆蟲學會了……\n他們沒有貪心地吃，不是一次全部吃。日復一日，他們只吸取膜的痕跡。它削弱了他們，扭曲了他們的內部——但沒有殺死他們。在許多週期中，只有那些能承受變化的昆蟲活了下來。",
    "Mycofall:Story_05.desc": "代代相傳變得更有抵抗力。這些殖民地的領導者開始選擇。他們只讓那些身體不排斥保護膜而是吸收它的後代活下來。從盾牌來的食物，從變化來的力量。就這樣，害蟲誕生了。無論它們觸及森林的何處，森林就開始腐爛。",
    "Mycofall:Story_06.desc": "森林再次面臨死亡的危機，曾經和平的Mykari不得不改變——就像他們的敵人一樣。曾經是他們盾牌的菌絲體現在被用來殺人。他們成為了戰士，甚至是那些從不想成為戰士的人。因為如果Mykari人民死亡，森林就會隨之倒下，協同力也會消退……",
    "Mycofall:general.title": "常規",
    "Mycofall:general.desc": "Mycofall是一款類似子彈天堂的生存者風格自動射擊遊戲。擊敗大量被感染的昆蟲，進化並改變強大的能力和武器。收集菌絲體，變得更強大，解鎖永久升級，並單獨或在線合作防衛森林。",
