    "UI:new": "新的",
    "UI:newsText.title": "你的旅程開始了",
    "UI:newsText.desc": "<b>嗨，Shroomer！</b>\n\n感謝你遊玩Mycofall Demo。這只是展示遊戲核心機制的一個預覽，還有更多等著你探索！更多技能、角色和地圖。內容和平衡仍在開發中，可能隨時更改。\n\n身為獨立開發者，我們非常依賴遊玩測試和玩家反饋。所以我們需要想法、意見和參與。歡迎加入我們的Discord！\n\n祝你遊玩愉快。\nStay shroomy！\n\nPS：「這款遊戲充滿了蟲子。」",
    "UI:howToPlay": "如何遊玩",
    "UI:demoEnd.title": "演示結束",
    "UI:demoEnd.desc": "嗨，Shroomer！\n\n感謝你遊玩Mycofall Demo。\n還有更多等著你！更多技能、角色和地圖。快點擊願望清單按鈕吧！\n\n別忘了加入Discord伺服器並分享你的意見。",
    "UI:bonus": "獎勵",
    "UI:artifactSelection": "神器獎勵",
    "UI:newsTextAlpha.title": "歡迎來到搶先體驗！",
    "UI:newsTextAlpha.desc": "嗨，Shroomer！\n\n很高興你在這裡。你是最先獨家了解Mycofall開發過程的玩家之一。內容和平衡仍在開發中，可能隨時更改。我們才剛開始這段旅程——如果你願意，可以成為其中的一部分。\n\n身為獨立開發者，我們非常依賴遊玩測試和玩家反饋。歡迎加入Discord！\n\n現在我們不想再耽誤你了——祝你遊玩愉快。\n\nStay shroomy！\n\nPS：「這款遊戲充滿了蟲子。",
    "UI:selectedEvolutionIndicator": "保持默認",
