    "UI:reward": "獎勵",
    "UI:gameOver.title": "遊戲結束",
    "UI:victory.title": "勝利",
    "UI:victory.desc": "你擊敗了Miss Mantis。\n但當你慶祝這小小勝利時，更多的昆蟲已經開始孵化。\n\n趕快回家——還是留下來迎接全面升級？",
    "UI:endless": "無盡升級",
    "UI:privacyPolicy": "隱私政策",
    "UI:firstTimePlayer.title": "歡迎，蘑菇愛好者！",
    "UI:firstTimePlayer.desc": "在你開始之前，我們建議你在第一局完成簡短的教程。它會指導你了解所有核心機制，這樣你就可以像專業人士一樣玩了！",
