    "Skills:plantBombs.title": "식물 폭탄",
    "Skills:fungalBlast.desc": "적을 향해 포자 투사체를 직선으로 발사한다.",
    "Skills:thorns.desc": "땅에서 가시 돋친 줄기를 소환하여 근처 적을 공격한다.",
    "Skills:spores.desc": "플레이어 주변에 포자로 가득 찬 오라를 방출하여 근처 적에게 주기적으로 피해를 준다.",
    "Skills:boomerang.desc": "플레이어에서 가시 달린 부메랑 투사체를 던져 경로의 모든 것을 공격한다.",
    "Skills:pineconeRain.desc": "하늘에서 솔방울 운석을 불러 적을 겨냥하고 충돌 시 범위 피해를 준다.",
    "Skills:plantBombs.desc": "넓은 범위에 식물 폭탄을 생성하며 플레이어가 기폭하면 범위 내 모든 적에게 범위 피해를 준다.",
    "Skills:slash.title": "부패의 칼날",
    "Skills:slash.desc": "플레이어 근처에서 부패의 칼날을 휘두른다. 영향 범위 내 모든 적이 피해를 받는다.",
    "Skills:beam.title": "균사 다리",
    "Skills:beam.desc": "가장 가까운 적에게 연결되어 지속적으로 피해를 준다.",
    "Characters:wortak.desc": "버티도록 만들어진 그는, 다른 이들이 쓰러지는 곳에서도 굳건히 선다.",
    "Characters:ensa.desc": "그녀는 비할 데 없는 우아함과 속도로 전장에 뛰어든다.",
