    "Interactables:RammhornRewardEvent.desc": "Lord Rammhorn 처치 후 보너스 유물 전리품을 생성한다.",
    "Resources:Amber.title": "호박",
    "Resources:Amber.desc": "게임 도중 더 비싼 모프 구매에 사용되는 보조 자원. 호박 상호작용 이벤트에서 생성되며 일부 유물이 부여한다.",
    "Resources:Biomass.title": "바이오매스",
    "Resources:Biomass.desc": "게임 도중 더 비싼 모프 구매에 사용되는 보조 자원. 적에게서 드랍되며 바이오매스 상호작용 이벤트에서 생성된다.",
    "Resources:MetaMushroom.title": "메타 균사체",
    "Resources:MetaMushroom.desc": "게임 도중 버섯 픽업에서 수집하는 영구 화폐. 게임 사이에 유지되며 허브에서 새로운 스킬, 맵, 캐릭터를 해금하는 데 사용된다.",
    "Resources:Mycelium.title": "균사체",
    "Resources:Mycelium.desc": "게임 도중 주요 화폐로, 적을 처치하거나 픽업으로 획득한다. 상점에서 스킬 모프를 구매하는 데 사용된다.",
