    "Mycofall:story.title": "스토리",
    "Mycofall:Story_01.desc": "오래전,\n숲이 아직 건강하고 생명으로 가득했을 때, Mykari는 숲과 조화를 이루며 살았습니다. 그들은 숲 바닥에서 자라난 작은 민족으로, 시너지의 힘을 통해 숲과 깊이 연결되어 있었습니다.",
    "Mycofall:Story_02.desc": "하지만 세월이 흐르면서 곤충들은 점점 더 많아지고 숲의 뿌리를 위협했습니다. 숲이 약해지고 Mykari도 역병에 시달리자, 시너지가 새로운 힘으로 깨어났습니다. 그녀는 Mykari에게 강력한 균사체를 만들고, 그것으로 숲 깊은 뿌리 위에 빛나는 보호막을 만드는 능력을 선물했습니다.",
    "Mycofall:Story_03.desc": "이 균사체를 먹은 곤충들은 독에 걸려 죽었고, 오랫동안 숲의 깊은 뿌리는 보호받았습니다…",
    "Mycofall:Story_04.desc": "하지만 곤충들은 배웠습니다…\n탐욕스럽게, 한꺼번에 먹지 않았습니다. 날마다 막의 흔적만을 조금씩 섭취했습니다. 그것은 그들을 약하게 만들고 내부를 뒤틀었지만, 죽이지는 못했습니다. 수많은 세대를 거쳐 변화를 견뎌낸 자들만이 살아남았습니다.",
    "Mycofall:Story_05.desc": "세대를 거듭할수록 더 강한 저항력을 갖게 되었습니다. 이 군집의 지도자들은 선택하기 시작했습니다. 보호막을 거부하지 않고 흡수하는 몸을 가진 후손들만을 살려두었습니다. 방패에서 식량이 왔습니다. 변화에서 힘이 왔습니다. 이렇게 역병 곤충이 탄생했습니다. 그들이 숲에 닿는 곳마다 숲은 썩기 시작합니다.",
    "Mycofall:Story_06.desc": "숲은 다시 죽음의 위기에 처했고, 한때 평화로웠던 Mykari는 적들처럼 변해야 했습니다. 한때 방패였던 균사체는 이제 죽이는 데 쓰였습니다. 그들은 전사가 되었습니다, 그것을 원하지 않았던 이들조차. 왜냐하면 Mykari 민족이 죽으면 숲도 함께 무너지고, 시너지도 사라지기 때문입니다…",
    "Mycofall:general.title": "일반",
    "Mycofall:general.desc": "Mycofall은 불렛 헤븐 스타일의 서바이버 자동 슈팅 게임입니다. 감염된 곤충 무리를 격퇴하여 강력한 능력과 무기를 진화시키고 변형합니다. 균사체를 수집하고, 더 강해지고, 영구 업그레이드를 잠금해제하고, 숲을 혼자 또는 온라인 협력 플레이로 방어합니다.",
