    "UI:new": "새로운",
    "UI:newsText.title": "당신의 여정이 시작됩니다",
    "UI:newsText.desc": "<b>안녕하세요, Shroomer!</b>\n\nMycofall 데모를 플레이해 주셔서 감사합니다. 이것은 게임의 핵심 메커니즘을 소개하는 쇼케이스일 뿐이며, 아직 더 많은 것이 기다리고 있습니다! 더 많은 스킬, 캐릭터, 맵. 콘텐츠와 밸런스는 아직 작업 중이며 언제든지 변경될 수 있습니다.\n\n인디 개발자로서 우리는 게임을 최대한 균형 잡히게 만들고 메커니즘을 다음 단계로 발전시키기 위해 플레이테스팅과 피드백에 크게 의존합니다. 그래서 아이디어, 피드백, 인상, 참여가 필요합니다. Discord에 참여해 주세요!\n\n게임을 즐겨주세요.\nStay shroomy!\n\nPS: '이 게임은 버그로 가득합니다.'",
    "UI:howToPlay": "플레이 방법",
    "UI:demoEnd.title": "데모 종료",
    "UI:demoEnd.desc": "안녕하세요, Shroomer!\n\nMycofall 데모를 플레이해 주셔서 감사합니다.\n더 많은 것이 기다리고 있습니다! 더 많은 스킬, 캐릭터, 맵. 위시리스트 버튼을 눌러주세요!\n\nDiscord 서버에 참가하고 공유하고 싶은 피드백을 남겨주세요.",
    "UI:bonus": "보너스",
    "UI:artifactSelection": "유물 보상",
    "UI:newsTextAlpha.title": "얼리 액세스에 오신 것을 환영합니다!",
    "UI:newsTextAlpha.desc": "안녕하세요, Shroomer!\n\n여기 오신 것을 환영합니다. Mycofall 개발 과정을 독점적으로 체험하는 첫 번째 분들 중 한 명입니다. 콘텐츠와 밸런스는 아직 작업 중이며 언제든지 변경될 수 있습니다. 우리는 이제 막 여정을 시작했으며, 원하신다면 그 일부가 될 수 있습니다.\n\n인디 개발자로서 우리는 플레이테스팅과 피드백에 크게 의존합니다. Discord에 참여해 주세요!\n\n이제 더 이상 붙잡지 않겠습니다 — 게임을 즐겨주세요.\n\nStay shroomy!\n\nPS: '이 게임은 버그로 가득합니다.",
    "UI:selectedEvolutionIndicator": "기본값 유지",
    "UI:waitingForHost": "호스트 대기 중",
    "UI:winDifficulty.title": "축하합니다",
    "UI:winDifficulty.desc": "새로운 난이도가 잠금 해제되었습니다.",
    "UI:tutorial": "튜토리얼",
    "UI:requiredLevel": "레벨 {0} 필요",
    "UI:default": "선택됨",
    "UI:maxSkillsReached": "최대 스킬 도달",
    "UI:credits": "크레딧",
    "UI:unseen": "미확인",
    "UI:reward": "보상",
    "UI:gameOver.title": "게임 오버",
    "UI:victory.title": "승리",
    "UI:victory.desc": "Miss Mantis를 처치했습니다.\n하지만 작은 승리를 자축하는 동안, 이미 더 많은 곤충들이 부화하고 있습니다.\n\n집으로 돌아가거나 — 완전한 혼돈을 즐겨볼까요?",
    "UI:endless": "무한 에스컬레이션",
    "UI:privacyPolicy": "개인정보 보호정책",
    "UI:firstTimePlayer.title": "환영합니다, 버섯 애호가!",
    "UI:firstTimePlayer.desc": "시작하기 전에 첫 번째 라운드에서 짧은 튜토리얼을 완료하기를 권장합니다. 모든 핵심 메커니즘을 안내하므로 전문가처럼 플레이할 준비가 될 것입니다!",
    "UI:quitConfirmation.title": "안녕히 가세요",
    "UI:quitConfirmation.desc": "플레이해주셔서 감사합니다. :) 피드백을 남겨주세요.",
    "UI:host": "호스트",
    "UI:join": "참가",
