    "Resources:Amber.title": "Bursztyn",
    "Resources:Amber.desc": "Drugorzędny zasób podczas rozgrywki używany do droższych zakupów Morfów. Generowany przez interaktywne wydarzenie Bursztyn i przyznawany przez niektóre artefakty.",
