    "Resources:MetaMushroom.title": "Meta-Grzybnia",
    "Resources:MetaMushroom.desc": "Trwała waluta zbierana z grzybów podczas rozgrywki. Przenosi się między rozgrywkami i wydawana jest w Centrum na odblokowywanie nowych umiejętności, map i postaci.",
    "Resources:Mycelium.title": "Grzybnia",
    "Resources:Mycelium.desc": "Główna waluta podczas rozgrywki, zarabiana przez pokonywanie wrogów i zbieranie przedmiotów. Wydawana w sklepie na Morfy umiejętności.",
