    "Mycofall:story.title": "Historia",
    "Mycofall:Story_01.desc": "Dawno temu,\ngdy las był jeszcze zdrowy i pełen życia, Mykari żyli z nim w harmonii. Byli małym ludem, który wyrósł z leśnej gleby i przez moc synergii był głęboko związany z lasem.",
    "Mycofall:Story_02.desc": "Lecz z biegiem lat owady stawały się coraz liczniejsze i zagrażały korzeniom lasu. Gdy las słabł, a Mykari cierpieli z powodu plagi, synergia przebudziła się z nową siłą. Obdarzyła Mykari darem formowania potężnej grzybni i tworzenia z niej mieniącej się ochronnej powłoki nad głębokimi korzeniami lasu.",
    "Mycofall:Story_03.desc": "Owady, które zjadały tę grzybnię, były trute i ginęły, a przez długi czas głębokie korzenie lasu pozostawały chronione…",
    "Mycofall:Story_04.desc": "Lecz owady się nauczyły…\nNie jadły zachłannie, nie wszystkiego naraz. Dzień po dniu brały jedynie ślady powłoki. Osłabiało je to, wypaczało ich wnętrze – ale ich nie zabijało. Przez wiele cykli przeżywały tylko te, które znosiły zmianę.",
    "Mycofall:Story_05.desc": "Pokolenie za pokoleniem stawało się bardziej odporne. Przywódcy tych kolonii zaczęli wybierać. Pozwalali żyć jedynie tym potomkom, których ciała nie odrzucały ochronnej powłoki, lecz ją wchłaniały. Z tarczy przyszło pożywienie. Ze zmiany przyszła moc. Tak narodziły się Owady Zarazy. Gdziekolwiek dotykają lasu, zaczyna on gnić.",
    "Mycofall:Story_06.desc": "Las znów był w niebezpieczeństwie, a Mykari, niegdyś pokojowi, musieli się zmienić – tak jak ich wrogowie. Grzybnia, która kiedyś była ich tarczą, teraz służyła do zabijania. Stali się wojownikami, nawet ci, którzy nigdy tego nie chcieli. Bo jeśli lud Mykari zginie, las upadnie razem z nim, a synergia zaniknie…",
    "Mycofall:general.title": "Ogólne",
    "Mycofall:general.desc": "Mycofall to gra typu bullet-heaven survivors z automatycznym strzelaniem. Pokonaj hordy zarażonych owadów, aby rozwijać i transformować potężne umiejętności i broń. Zbieraj miceliję, wzmacniaj się, odblokowuj permanentne ulepszenia i bronić las sam lub razem we wspólnej grze online.",
