    "UI:new": "Nowe",
    "UI:newsText.title": "Twoja Podróż Się Zaczyna",
    "UI:newsText.desc": "<b>Hej Shroomer,</b>\n\ndziękujemy za granie w demo Mycofall. To tylko pokaz podstawowych mechanik gry, ale jest więcej do odkrycia! Więcej umiejętności, postaci i map. Zawartość i balans są nadal w trakcie prac i mogą ulec zmianie.\n\nJako niezależni deweloperzy mocno polegamy na playtestach i opiniach. Dlatego potrzebujemy pomysłów, feedbacku i zaangażowania. Serdecznie zapraszamy na nasz Discord.\n\nBaw się dobrze!\nStay shroomy!\n\nPS: 'Ta gra jest pełna bugów.'",
    "UI:howToPlay": "Jak grać",
    "UI:demoEnd.title": "KONIEC DEMA",
    "UI:demoEnd.desc": "Hej Shroomer,\n\ndziękujemy za granie w demo Mycofall.\nJest więcej do odkrycia! Więcej umiejętności, postaci i map. Kliknij przycisk wishlisty!\n\nNie zapomnij dołączyć do serwera Discord i podzielić się swoją opinią.",
    "UI:bonus": "Bonus",
    "UI:artifactSelection": "Nagroda artefaktu",
    "UI:newsTextAlpha.title": "Witaj we wczesnym dostępie!",
    "UI:newsTextAlpha.desc": "Hej Shroomer,\n\nświetnie, że tu jesteś. Jesteś wśród pierwszych, którzy mają ekskluzywny wgląd w proces tworzenia Mycofall. Zawartość i balans są nadal w trakcie prac. Jesteśmy dopiero na początku naszej drogi — jeśli chcesz, możesz być jej częścią.\n\nJako niezależni deweloperzy polegamy na playtestach i opiniach. Zapraszamy na Discord!\n\nNie chcemy cię już dłużej zatrzymywać — baw się dobrze.\n\nStay shroomy!\n\nPS: 'Ta gra jest pełna bugów.",
    "UI:selectedEvolutionIndicator": "ZACHOWAJ DOMYŚLNE",
