    "UI:winDifficulty.title": "Gratulacje",
    "UI:winDifficulty.desc": "Odblokujesz nowy poziom trudności.",
    "UI:tutorial": "Samouczek",
    "UI:requiredLevel": "Wymagany poziom {0}",
    "UI:default": "WYBRANE",
    "UI:maxSkillsReached": "Osiągnięto maks. umiejętności",
    "UI:credits": "Napisy końcowe",
    "UI:unseen": "Niewidziane",
    "UI:reward": "Nagroda",
    "UI:gameOver.title": "Koniec gry",
    "UI:victory.title": "Zwycięstwo",
    "UI:victory.desc": "Pokonałeś Miss Mantis.\nAle gdy świętować masz tę małą wiktorię, jeszcze więcej owadów już wylęga się z jaj.\n\nUciekaj do domu — albo zostań i mierz się z totalną eskalacją?",
    "UI:endless": "Nieskończona eskalacja",
    "UI:privacyPolicy": "Polityka prywatności",
    "UI:firstTimePlayer.title": "Witaj, miłośniku grzybów!",
    "UI:firstTimePlayer.desc": "Zanim zaczniesz, sugerujemy ukończenie krótkiego samouczka w pierwszej rundzie. Przeprowadzi cię przez wszystkie podstawowe mechaniki, abyś był gotów grać jak profesjonalista!",
    "UI:quitConfirmation.title": "Do widzenia",
    "UI:quitConfirmation.desc": "Dzięki za grę. :) Chętnie usłyszymy twoją opinię.",
