    "Codex:Mycofall.title": "Mycofall",
    "Codex:Mycofall.desc": "História",
    "Codex:Character.title": "Personagens",
    "Codex:Character.desc": "Escolha entre personagens únicos, cada um com seus próprios conjuntos de vantagens e traços.",
    "Codex:Skill.title": "Habilidades",
