    "Codex:Artifact.title": "Artefatos",
    "Codex:Artifact.desc": "Itens poderosos com efeitos passivos únicos. Encontrados como recompensas de onda ou desbloqueios de missão.",
    "Codex:Interactable.title": "Interativos",
    "Codex:Interactable.desc": "Interativos são objetos que aparecem no mundo durante uma partida com diferentes chances. Fique perto para carregá-los — quanto mais jogadores por perto, mais rápido ativa — e então dispara seu efeito.",
    "Codex:Enemy.title": "Inimigos",
