    "Mycofall:story.title": "História",
    "Mycofall:Story_01.desc": "Há muito tempo,\nquando a floresta ainda era saudável e cheia de vida, os Mykari viviam em harmonia com ela. Eram um pequeno povo que crescia do chão da floresta e estava profundamente conectado a ela pelo poder da sinergia.",
    "Mycofall:Story_02.desc": "Mas com o passar dos anos, os insetos se tornaram cada vez mais numerosos e ameaçaram as raízes da floresta. Enquanto a floresta enfraquecia e os Mykari sofriam com a praga, a sinergia despertou com nova força. Ela deu aos Mykari o dom de moldar um poderoso micélio e usá-lo para criar uma película protetora cintilante sobre as raízes profundas da floresta.",
    "Mycofall:Story_03.desc": "Os insetos que comiam este micélio eram envenenados e morriam, e por muito tempo as raízes profundas da floresta permaneceram protegidas…",
    "Mycofall:Story_04.desc": "Mas os insetos aprenderam…\nNão comiam com avidez, não tudo de uma vez. Dia após dia, tomavam apenas traços da película. Isso os enfraquecia, distorcia seu interior – mas não os matava. Ao longo de muitos ciclos, apenas aqueles que suportavam a mudança sobreviviam.",
    "Mycofall:Story_05.desc": "Geração após geração tornaram-se mais resistentes. Os líderes dessas colônias começaram a escolher. Deixavam viver apenas os descendentes cujos corpos não rejeitavam a película protetora, mas a absorviam. Do escudo veio o alimento. Da mudança veio o poder. Assim nasceram os Insetos-Praga. Onde quer que toquem a floresta, ela começa a apodrecer.",
    "Mycofall:Story_06.desc": "A floresta estava em perigo de morrer novamente, e os Mykari, antes pacíficos, tiveram que mudar – assim como seus inimigos. O micélio que antes era seu escudo agora era usado para matar. Tornaram-se guerreiros, até mesmo aqueles que nunca quiseram ser. Pois se o povo dos Mykari morrer, a floresta cai com eles, e a sinergia desaparece…",
    "Mycofall:general.title": "Geral",
    "Mycofall:general.desc": "Mycofall é um jogo de tiro automático estilo bullet-heaven survivors. Derrote hordas de insetos infectados para evoluir e transformar poderosas habilidades e armas. Colete micélio, fique mais forte, desbloqueie melhorias permanentes e defenda a floresta sozinho ou juntos no co-op online.",
