    "UI:statistics": "Estatísticas",
    "UI:new": "Novo",
    "UI:newsText.title": "Sua Jornada Começa",
    "UI:newsText.desc": "<b>Olá, Shroomer!</b>\n\nObrigado por jogar o demo do Mycofall. Isso é apenas uma vitrine das mecânicas centrais do jogo, mas há muito mais a descobrir! Mais habilidades, personagens e mapas. O conteúdo e o equilíbrio ainda estão em desenvolvimento e podem mudar a qualquer momento.\n\nComo desenvolvedores indie, dependemos muito de playtests e feedbacks. Por isso precisamos de ideias, impressões e envolvimento. Venha ao nosso Discord!\n\nDivirta-se!\nStay shroomy!\n\nPS: 'Este jogo está cheio de bugs.'",
    "UI:howToPlay": "Como Jogar",
    "UI:demoEnd.title": "FIM DO DEMO",
    "UI:demoEnd.desc": "Olá, Shroomer!\n\nObrigado por jogar o demo do Mycofall.\nTem mais a descobrir! Mais habilidades, personagens e mapas. Clique no botão da lista de desejos!\n\nNão esqueça de entrar no servidor do Discord e deixar seu feedback.",
    "UI:bonus": "Bônus",
    "UI:artifactSelection": "Recompensa de Artefato",
    "UI:newsTextAlpha.title": "Bem-vindo ao Acesso Antecipado!",
    "UI:newsTextAlpha.desc": "Olá, Shroomer!\n\nQue bom ter você aqui. Você está entre os primeiros a ter acesso exclusivo ao processo de desenvolvimento do Mycofall. O conteúdo e o equilíbrio ainda estão em andamento. Estamos apenas no começo da nossa jornada — se quiser, pode fazer parte dela.\n\nComo desenvolvedores indie, dependemos de playtests e feedbacks. Venha ao nosso Discord!\n\nMas não queremos te deter por mais tempo — divirta-se.\n\nStay shroomy!\n\nPS: 'Este jogo está cheio de bugs.",
    "UI:selectedEvolutionIndicator": "MANTER PADRÃO",
