    "UI:victory.title": "Vitória",
    "UI:victory.desc": "Você derrotou Miss Mantis.\nMas enquanto comemora sua pequena vitória, ainda mais insetos já estão eclodindo.\n\nCorra para casa — ou fique para a escalada total?",
    "UI:endless": "Escalada infinita",
    "UI:privacyPolicy": "Política de privacidade",
