    "Mycofall:story.title": "Hikaye",
    "Mycofall:Story_01.desc": "Çok uzun zaman önce,\norman hâlâ sağlıklı ve hayat doluyken, Mykari onunla uyum içinde yaşıyordu. Orman zemininden büyüyen küçük bir halktı ve sinerji gücüyle ormana derinden bağlıydılar.",
    "Mycofall:Story_02.desc": "Ancak yıllar geçtikçe böcekler giderek çoğaldı ve ormanın köklerini tehdit etmeye başladı. Orman zayıflayıp Mykari da beladan muzdarip olunca, sinerji yeni bir güçle uyandı. Mykari'ye güçlü bir misel şekillendirme ve bunu kullanarak ormanın derin köklerinin üzerine parlak bir koruyucu film oluşturma yeteneğini bağışladı.",
    "Mycofall:Story_03.desc": "Bu miseli yiyen böcekler zehirlenerek öldü ve uzun süre ormanın derin kökleri korunaklı kaldı…",
    "Mycofall:Story_04.desc": "Ama böcekler öğrendi…\nHırsla, hepsini bir anda yemiyorlardı. Gün be gün yalnızca filmden izler alıyorlardı. Bu onları zayıflattı, içlerini çarpıttı — ama öldürmedi. Pek çok döngü boyunca yalnızca değişime dayananlar hayatta kaldı.",
    "Mycofall:Story_05.desc": "Nesil nesil daha dirençli hale geldiler. Bu kolonilerin liderleri seçim yapmaya başladı. Yalnızca koruyucu filmi reddetmeyen, onu emen bedenlere sahip torunların yaşamasına izin verdiler. Kalkandan yiyecek geldi. Değişimden güç geldi. Böylece Veba Böcekleri doğdu. Ormana dokundukları her yerde orman çürümeye başlar.",
    "Mycofall:Story_06.desc": "Orman yeniden ölüm tehlikesiyle karşı karşıyaydı ve bir zamanlar barışçıl olan Mykari, tıpkı düşmanları gibi değişmek zorunda kaldı. Bir zamanlar kalkan olan misel, artık öldürmek için kullanılıyordu. Hiç olmak istemeyenler de dahil olmak üzere, hepsi savaşçı oldu. Zira Mykari halkı ölürse, orman da onlarla birlikte düşer ve sinerji solar…",
    "Mycofall:general.title": "Genel",
    "Mycofall:general.desc": "Mycofall, bullet-heaven tarzı bir survivors otomatik atıcı oyunudur. Enfekte olmuş böceklerin ordularını yene, güçlü yetenekleri ve silahları evrimleştir ve değiştir. Misel topla, daha güçlü ol, kalıcı yükseltmeleri açın ve ormanı tek başına veya çevrimiçi işbirliğinde birlikte savunun.",
