    "UI:newsText.title": "Yolculuğun Başlıyor",
    "UI:newsText.desc": "<b>Merhaba, Shroomer!</b>\n\nMycofall demosunu oynadığın için teşekkürler. Bu yalnızca oyunun temel mekaniklerini tanıtan bir vitrin — keşfedilecek çok daha fazlası var! Daha fazla beceri, karakter ve harita. İçerik ve denge hâlâ geliştirilmekte olup her an değişebilir.\n\nBağımsız geliştiriciler olarak oyun testine ve geri bildirimlere büyük önem veriyoruz. Bu yüzden fikir, geri bildirim ve katılıma ihtiyacımız var. Discord sunucumuza katılmaya davetlisin!\n\nOyunun tadını çıkar.\nStay shroomy!\n\nPS: 'Bu oyun böcek dolu.'",
    "UI:howToPlay": "Nasıl Oynanır",
    "UI:demoEnd.title": "DEMO SONU",
    "UI:demoEnd.desc": "Merhaba, Shroomer!\n\nMycofall demosunu oynadığın için teşekkürler.\nKeşfedilecek daha fazlası var! Daha fazla beceri, karakter ve harita. İstek listesi butonuna bas!\n\nDiscord sunucusuna katılmayı ve geri bildirim bırakmayı unutma.",
    "UI:bonus": "Bonus",
    "UI:artifactSelection": "Eser Ödülü",
    "UI:newsTextAlpha.title": "Erken Erişime Hoş Geldiniz!",
    "UI:newsTextAlpha.desc": "Merhaba, Shroomer!\n\nBurada olman harika. Mycofall geliştirme sürecine özel bir bakış açısı kazanan ilkler arasındasın. İçerik ve denge hâlâ geliştirilmekte — yolculuğumuzun başındayız ve istersen bir parçası olabilirsin.\n\nBağımsız geliştiriciler olarak oyun testine ve geri bildirimlere büyük önem veriyoruz. Discord'a katıl!\n\nAma artık seni daha fazla tutmak istemiyoruz — oyunun tadını çıkar.\n\nStay shroomy!\n\nPS: 'Bu oyun böcek dolu.",
